export type Decision = 'keep' | 'revoke' | 'pending';

export interface ReviewItem { userId: string; role: Role; reviewerId: string; decision: Decision; decidedAt?: string; idleDays: number }

export async function openCampaign(quarter: string, reviewers: string[]): Promise<Campaign> {
  const users = await listUsers();
  const items = users.flatMap((u) => u.roles.filter(isPrivileged).map((role) => ({ userId: u.id, role, reviewerId: assignReviewer(u.id, reviewers), decision: 'pending' as const, idleDays: idleDays(u) })));
  return db.campaigns.insert({ quarter, items, status: 'open' });
}

export async function decide(item: ReviewItem, actorId: string, decision: Decision): Promise<void> {
  if (item.userId === actorId) throw new Forbidden('separation of duties: no self-review');
  if (decision === 'revoke') {
    await setRoles(item.userId, (await rolesOf(item.userId)).filter((r) => r !== item.role));
    await revokeSessionsFor(item.userId);
  }
  audit({ actor: actorId, action: `review.${decision}`, target: `user:${item.userId}:${item.role}` });
}

