export function AccessReviews({ campaign }: { campaign: Campaign }) {
  const pending = campaign.items.filter((i) => i.decision === 'pending');
  return (
    <section aria-labelledby='reviews-title'>
      <h2 id='reviews-title'>Access review {campaign.quarter}</h2>
      <p>{pending.length} of {campaign.items.length} grants awaiting a decision</p>
      <ReviewTable items={campaign.items} onDecide={decide} />
      <button disabled={pending.length > 0} onClick={() => closeCampaign(campaign.id)}>Close and export evidence</button>
    </section>
  );
}
